javascript.code:
function* fibonacci() {
  let a = 0
  let b = 1
  while (true) {
    yield a
    const next = a + b
    a = b
    b = next
  }
}

function take(iterable, count) {
  const out = []
  if (count <= 0) return out
  for (const value of iterable) {
    out.push(value)
    if (out.length === count) break
  }
  return out
}

console.log(take(fibonacci(), 10).join(' '))

typescript.code:
function* fibonacci(): Generator<number> {
  let a = 0
  let b = 1
  while (true) {
    yield a
    const next = a + b
    a = b
    b = next
  }
}

function take<T>(iterable: Iterable<T>, count: number): T[] {
  const out: T[] = []
  if (count <= 0) return out
  for (const value of iterable) {
    out.push(value)
    if (out.length === count) break
  }
  return out
}

console.log(take(fibonacci(), 10).join(' '))

